class Solution {
public:
    string minimizeError(vector<string>& prices, int target) {
        int floorSum = 0;
        vector<int> fractions;
        for (const string& price : prices) {
            int value = stoi(price.substr(0, price.find('.')));
            int fraction = stoi(price.substr(price.find('.') + 1));
            floorSum += value;
            if (fraction > 0) {
                fractions.push_back(fraction);
            }
        }
        int up = target - floorSum;
        if (up < 0 || up > static_cast<int>(fractions.size())) {
            return "-1";
        }
        sort(fractions.rbegin(), fractions.rend());
        int error = 0;
        for (int i = 0; i < static_cast<int>(fractions.size()); ++i) {
            error += (i < up) ? (1000 - fractions[i]) : fractions[i];
        }
        ostringstream out;
        out << fixed << setprecision(3) << error / 1000.0;
        return out.str();
    }
};
